"""Demo: radius-independent complete energy capture of a Dyson shell."""
from __future__ import annotations
import math

L_SUN: float = 3.828e26       # solar luminosity (W)
AU: float = 1.495978707e11    # astronomical unit (m)

def dyson_area(radius: float) -> float:
    return 4.0 * math.pi * radius ** 2

def sphere_flux(luminosity: float, radius: float) -> float:
    return luminosity / (4.0 * math.pi * radius ** 2)

def captured_power(luminosity: float, radius: float) -> float:
    return sphere_flux(luminosity, radius) * dyson_area(radius)

if __name__ == "__main__":
    print(f"{'R (AU)':>8} | {'flux (W/m^2)':>14} | {'area (m^2)':>12} | {'captured (W)':>14}")
    for r_au in (0.4, 1.0, 5.2, 30.0):
        r = r_au * AU
        print(f"{r_au:8.1f} | {sphere_flux(L_SUN, r):14.3e} | "
              f"{dyson_area(r):12.3e} | {captured_power(L_SUN, r):14.6e}")
    print(f"\\nStar luminosity = {L_SUN:.6e} W (equals captured power at every radius)")

"""Demo: Landauer storage and Margolus-Levitin computation ceilings."""
from __future__ import annotations
import math

K_B: float = 1.380649e-23      # Boltzmann constant (J/K)
HBAR: float = 1.054571817e-34  # reduced Planck constant (J s)
LN2: float = math.log(2.0)

def landauer_bits(energy: float, k_b: float, temperature: float) -> float:
    return energy / (k_b * temperature * LN2)

def ml_op_rate(energy: float, hbar: float) -> float:
    return 2.0 * energy / (math.pi * hbar)

if __name__ == "__main__":
    print("Landauer storage-temperature duality (bits * T invariant at fixed E):")
    energy = 1.0e30
    for temp in (100.0, 200.0, 400.0):
        b = landauer_bits(energy, K_B, temp)
        print(f"  T = {temp:6.1f} K -> {b:.3e} bits, bits*T = {b*temp:.3e}")
    print("\\nMargolus-Levitin operation-rate ceiling (strictly increasing in power):")
    for power in (1e17, 1e20, 1e26):
        rate = ml_op_rate(power, HBAR)
        print(f"  P = {power:.0e} W -> {rate:.3e} ops/s")

