"""Solve for the orbital radius achieving a target equilibrium temperature."""
from __future__ import annotations
import math

SIGMA_SB: float = 5.670374419e-8

def eq_temp_at_radius(power: float, radius: float, faces: int) -> float:
    area: float = faces * 4.0 * math.pi * radius ** 2
    return (power / (SIGMA_SB * area)) ** 0.25

def radius_for_temperature(power: float, target_T: float, faces: int,
                           lo: float, hi: float, tol: float = 1e-6) -> float:
    """Bisection: temperature is strictly antitone in area (hence in radius),
    guaranteeing a unique root when the target lies within [T(hi), T(lo)]."""
    for _ in range(200):
        mid = 0.5 * (lo + hi)
        if eq_temp_at_radius(power, mid, faces) > target_T:
            lo = mid          # too hot -> need larger radius
        else:
            hi = mid
        if hi - lo < tol * mid:
            break
    return 0.5 * (lo + hi)

if __name__ == "__main__":
    L_SUN, AU = 3.828e26, 1.495978707e11
    r = radius_for_temperature(L_SUN, 300.0, faces=2, lo=0.1*AU, hi=100.0*AU)
    print(f"Radius for 300 K swarm: {r/AU:.4f} AU")
    print(f"Check temperature      : {eq_temp_at_radius(L_SUN, r, 2):.3f} K")
